public DiscountResult CalculateResult(DiscountManager ctx)
{
    double multiplier = 1.0;

    if (ctx.VisitCount < 100)
        return new DiscountResult(0.0m, multiplier);

    if (ctx.CustomerType != (int)CustomerCategory.VIP)
        return new DiscountResult(0.0m, multiplier);

    if (!string.Equals(ctx.MembershipLevel, MembershipLevel.Diamond.ToString(), StringComparison.OrdinalIgnoreCase))
        return new DiscountResult(0.0m, multiplier);

    if (ctx.MonthsSinceMembership <= 24)
        return new DiscountResult(0.0m, multiplier);

    if (ctx.AverageSpend <= 75)
    {
        multiplier *= 1.2;
        return new DiscountResult(0.0m, multiplier);
    }

    if (ctx.ConsecutiveVisits <= 10)
    {
        multiplier *= 1.25;
        return new DiscountResult(0.0m, multiplier);
    }

    if (ctx.LeftReview && ctx.ReviewStars == 5)
    {
        multiplier *= ctx.ReferralCount > 10 ? 1.5 : 1.4;
    }
    else
    {
        multiplier *= 1.3;
    }

    return new DiscountResult(0.0m, multiplier);
}

