private decimal RushHourPenalty(DiscountManager ctx)
{
    if (!ctx.IsRushHour) return 0.0m;

    // Midday penalty (12:00-13:59)
    if (ctx.Hour >= 12 && ctx.Hour <= 13)
    {
        if (!ctx.IsDriveThru) return -5.0m;

        if (ctx.ItemCount < 5) return -8.0m;

        if (ctx.CustomerType != (int)CustomerCategory.VIP) return -12.0m;

        // VIP path
        if (string.Equals(ctx.MembershipLevel, MembershipLevel.Diamond.ToString(), StringComparison.OrdinalIgnoreCase))
            return ctx.VisitCount > 100 ? -2.0m : -5.0m;

        return -8.0m;
    }

    // Evening penalty (18:00-19:59)
    if (ctx.Hour >= 18 && ctx.Hour <= 19) return -10.0m;

    return 0.0m;
}
